const trig = $('Store Settings').first().json;

const txt = (a) => (a || []).map(t => t.plain_text).join('');
const rt = (p) => (p ? txt(p.rich_text || p.title) : '');
const sel = (p) => (p && p.select ? p.select.name : null);
const num = (p) => (p && typeof p.number === 'number' ? p.number : null);
const dt = (p) => (p && p.date && p.date.start ? p.date.start.slice(0, 10) : null);
const rel = (p) => (p && Array.isArray(p.relation) ? p.relation.map(r => r.id) : []);
const pagesOf = (n) => {
  try { return $(n).all().map(i => i.json).filter(p => p && p.properties); } catch (e) { return []; }
};
const show = (v) => (v === null || v === undefined || v === '' ? '-' : v);

const weekMon = $now.startOf('week').toISODate();
const weekSun = $now.endOf('week').toISODate();

// Projects, weekly items and tasks come from the shared "Read Plan Tree" (the Productivity Agent reads the same tree)
let tree = {};
try { tree = $('Read Plan Tree').first().json || {}; } catch (e) { tree = {}; }
const treeFailed = !Array.isArray(tree.projects);

// Projects (outcome fields only; how the work is done lives in the weekly items)
const projects = (tree.projects || []).map(f => {
  const ok = (b) => (b ? '✅' : '❌');
  const S = !!f.goal && !!f.oos, M = !!f.metric && f.baseline !== null && f.target !== null, A = !!f.who;
  const R = f.chance !== null && f.prediction !== null && f.low !== null && f.high !== null;
  const T = !!f.deadline && !!f.checkpoints, W = !!f.why;
  const smart = 'S' + ok(S) + ' M' + ok(M) + ' A' + ok(A) + ' R' + ok(R) + ' T' + ok(T) + ' Why' + ok(W);
  const smartDone = f.smartBox === null || f.smartBox === undefined ? (S && M && A && R && T && W) : f.smartBox; // Notion's own formula wins
  return { ...f, smart, smartDone };
});
const projName = Object.fromEntries(projects.map(p => [p.id, p.name]));

// Weekly reviews
const reviews = pagesOf('Fetch Recent Reviews').map(pg => {
  const p = pg.properties;
  const r = {
    id: pg.id, week: dt(p['Week']), project: rel(p['Project'])[0] || null,
    predicted: num(p['Predicted']), low: num(p['Range Low']), high: num(p['Range High']), actual: num(p['Actual']),
    lever: sel(p['Lever Actions Done']), leaks: rt(p['Time Leaks']), blockers: rt(p['New Blockers']),
    decision: sel(p['Decision']), lesson: rt(p['Lesson'])
  };
  r.inRange = r.actual === null || r.low === null || r.high === null ? null : (r.actual >= r.low && r.actual <= r.high);
  return r;
}).filter(r => r.week).sort((a, b) => (a.week < b.week ? 1 : -1));
// A number is scored only for money projects (their Metric is money); every other project is scored by its goals' quality bar
const isMoney = (pid) => { const p = projects.find(x => x.id === pid); return !!(p && /€|\beur\b|\bpln\b|usd|\$|money|earn|income|revenue/i.test(p.metric || '')); };
const scored = reviews.filter(r => r.inRange !== null && isMoney(r.project));
const hits = scored.filter(r => r.inRange).length;

// Weekly items and this week's daily tasks, from the tree
const plan = (tree.goals || []).filter(i => i.due);
const planById = Object.fromEntries(plan.map(i => [i.id, i]));
const tasks = (tree.tasks || []).filter(t => t.due && t.due >= weekMon && t.due <= weekSun).map(t => ({
  name: t.name, status: t.status, due: t.due, moved: t.moved || 0, wk: t.weekly_item,
  project: t.weekly_item && planById[t.weekly_item] ? planById[t.weekly_item].project : null,
  personal: t.weekly_item && planById[t.weekly_item] ? planById[t.weekly_item].link_status === 'Personal' : false
}));
const byProject = {};
for (const t of tasks) {
  const k = t.project ? (projName[t.project] || 'a closed project') : (t.personal ? 'Personal (no project)' : 'UNLINKED (not tied to any project)');
  byProject[k] = byProject[k] || { done: 0, open: 0, cancelled: 0, moved: 0 };
  const b = byProject[k];
  if (t.status === 'Done') b.done++; else if (t.status === 'Cancelled') b.cancelled++; else b.open++;
  if (t.moved > 0) b.moved++;
}

// Calendar this week (read only on the weekend or when the message is about the week)
const weekDetail = $('Fetch Week Calendar').isExecuted;
const events = (weekDetail ? $('Fetch Week Calendar').all() : []).map(i => i.json).filter(e => e && e.start).map(e => {
  const s = e.start.dateTime || e.start.date, en = e.end ? (e.end.dateTime || e.end.date) : null;
  const hrs = e.start.dateTime && en ? Math.round((DateTime.fromISO(en) - DateTime.fromISO(s)) / 36e5 * 10) / 10 : null;
  return { title: e.summary || '(no title)', day: String(s).slice(0, 10), hours: hrs };
});
const calHours = Math.round(events.filter(e => e.day <= weekSun).reduce((a, e) => a + (e.hours || 0), 0) * 10) / 10;

// Ideas
const ideas = pagesOf('Fetch Project Ideas').map(pg => {
  const p = pg.properties;
  return {
    id: pg.id, name: rt(p['Idea Name']), status: sel(p['Status']), verdict: sel(p['Verdict']),
    metric: rt(p['Success Metric']), target: num(p['Target']), test: rt(p['Cheapest Test']), testBy: dt(p['Test By'])
  };
});

// Long-term memory from Notion, read on every message (the agent's own page and the shared page): what he asked to remember
const memText = (n) => { try { const j = $(n).first().json; return typeof j.markdown === 'string' ? j.markdown.split('\n').filter((l) => !l.startsWith('>')).join('\n').trim() : null; } catch (e) { return null; } };
const ownMem = memText('Fetch Agent Memory'), sharedMem = memText('Fetch Shared Memory');
const memFailed = [ownMem === null ? 'your memory page' : '', sharedMem === null ? 'the shared memory page' : ''].filter(Boolean);
const memory = 'WHAT YOU KNOW ABOUT ALEX (your Notion memory, read just now: apply every line)\n' + (memFailed.length ? 'MEMORY READ FAILED for ' + memFailed.join(' and ') + ': call Recall Memory once.\n' : '') + '# Shared page (all agents)\n' + (sharedMem || '-') + '\n# Your page\n' + (ownMem || '-');
const out = [memory, ''];
out.push('Read just now (' + $now.toFormat('yyyy-LL-dd HH:mm') + '). This week: ' + weekMon + ' to ' + weekSun + '.');
// A read that failed returns an error item instead of rows: say so, so an empty list is not read as "nothing there"
const failedReads = ['Fetch Recent Reviews', 'Fetch Week Calendar', 'Fetch Project Ideas'].filter(n => { try { return $(n).all().some(i => i.json && i.json.error); } catch (e) { return n !== 'Fetch Week Calendar'; } });
if (treeFailed) failedReads.push('Read Plan Tree');
for (const n of (tree.read_failed || [])) failedReads.push(n);
if (failedReads.length) out.push('NOTION READ FAILED: ' + failedReads.join(', ') + '. Those sections may be incomplete.');

const active = projects.filter(p => p.status === 'Active');
const rankOf = (r) => active.filter(p => p.rank === r).map(p => p.name).join(', ') || 'none';
out.push('', 'PROJECTS (outcomes only; Active: Rank 1 ' + rankOf(1) + ' · Rank 2 ' + rankOf(2) + ' · Rank 3 ' + rankOf(3) + ' · On Hold ' + (projects.filter(p => p.status === 'On Hold').map(p => p.name).join(', ') || 'none') + ')');
if (!projects.length) out.push('No open projects.');
for (const p of projects) {
  out.push('- ' + p.name + ' [id ' + p.id + '] · ' + show(p.status) + ' · Rank ' + show(p.rank) + ' · Iteration ' + show(p.iteration) + ' · ' + p.smart + (p.smartDone ? ' (SMART Complete box ticked in Notion)' : ' (SMART Complete box NOT ticked in Notion)'));
  out.push('  Why: ' + show(p.why) + ' | Goal: ' + show(p.goal) + ' | Out of scope: ' + show(p.oos));
  out.push('  Metric: ' + show(p.metric) + ' | Baseline ' + show(p.baseline) + ' -> Target ' + show(p.target) + ' by ' + show(p.deadline) + ' | Who: ' + show(p.who));
  out.push('  Chance ' + show(p.chance) + '% | Prediction ' + show(p.prediction) + ' (80% range ' + show(p.low) + '-' + show(p.high) + ') | Checkpoints: ' + show(p.checkpoints));
  out.push('  Blockers: ' + show(p.blockers) + ' | Assumptions: ' + show(p.assumptions) + (p.parked ? ' | Parked because: ' + p.parked : '') + (p.notes ? ' | Notes: ' + p.notes : ''));
}

out.push('', 'WEEKLY REVIEWS (last 6 weeks, newest first; a predicted number only for money projects, frozen once set)');
if (!reviews.length) out.push('None yet.');
for (const r of reviews) {
  const money = isMoney(r.project) ? ' · money: predicted ' + show(r.predicted) + ' (range ' + show(r.low) + '-' + show(r.high) + ') · actual ' + show(r.actual) + (r.inRange === null ? '' : (r.inRange ? ' · IN range' : ' · OUT of range')) : '';
  out.push('- Week ending ' + r.week + ' · ' + (projName[r.project] || 'closed project') + ' [review id ' + r.id + ']' + money + ' · decision ' + show(r.decision) + (r.lesson ? ' · lesson: ' + r.lesson : ''));
}
// Quality calibration: goals of the last 12 weeks that have a Result, grouped by the confidence he gave
const cal = {};
const bucket = (c) => (c === null || c === undefined ? 'no confidence given' : c < 50 ? 'under 50%' : c < 80 ? '50-79%' : '80% or more');
for (const g of (tree.scored_goals || [])) {
  const b = bucket(g.confidence); cal[b] = cal[b] || { met: 0, partly: 0, total: 0 };
  cal[b].total++; if (g.result === 'Met') cal[b].met++; else if (g.result === 'Partly') cal[b].partly++;
}
out.push('Quality calibration (goals of the last 12 weeks with a Result, by the confidence he gave): ' + (Object.keys(cal).length ? Object.entries(cal).map(([b, c]) => b + ': met ' + c.met + ' of ' + c.total + (c.partly ? ' (' + c.partly + ' partly)' : '')).join(' · ') : 'none scored yet.'));
out.push('Money calibration (money projects only): ' + hits + ' of ' + scored.length + ' scored weeks inside the range.');

out.push('', tree.text || 'PLAN TREE: not available (Read Plan Tree failed).');

// Last week's goals without a Result: what a review held from Monday to Friday scores
const lw = tree.last_week_goals || [];
const lastSun = $now.startOf('week').minus({ days: 1 }).toISODate();
out.push('', 'LAST WEEK\'S GOALS NOT SCORED YET (week ending ' + lastSun + '; a review held from Monday to Friday scores these, not this week\'s)');
if (!lw.length) out.push('None.');
for (const g of lw) out.push('- "' + g.name + '" [id ' + g.id + '] · project: ' + (g.project ? (projName[g.project] || 'closed project') : (g.link_status || 'none')) + ' · ' + show(g.status) + (g.done_when ? ' · done when: ' + g.done_when.replace(/\s+/g, ' ') : ' · no Done When') + (g.confidence !== null && g.confidence !== undefined ? ' · confidence ' + g.confidence + '%' : ''));

out.push('', 'DAILY TASKS DUE THIS WEEK (the totals are for one line only; never ask about a single task)');
if (weekDetail && tasks.length) {
  const tot = { done: 0, open: 0, cancelled: 0, moved: 0 };
  for (const t of tasks) { if (t.status === 'Done') tot.done++; else if (t.status === 'Cancelled') tot.cancelled++; else tot.open++; if (t.moved > 0) tot.moved++; }
  out.push('- All tasks: done ' + tot.done + ', open ' + tot.open + ', cancelled ' + tot.cancelled + ', moved at least once ' + tot.moved);
  const canc = tasks.filter(t => t.status === 'Cancelled').map(t => t.name);
  if (canc.length) out.push('- Cancelled (context only, often a cleanup of old or duplicate rows): ' + canc.join('; '));
  out.push('By project (through their weekly item):');
}
if (!weekDetail) out.push('Not loaded for this message (the task totals are read only on Saturday, Sunday, or when the message is about the week). Do not say there are none; ask him to say "weekly review" if you need them.');
else if (!tasks.length) out.push('No daily tasks this week.');
if (weekDetail) for (const [k, b] of Object.entries(byProject)) {
  out.push('- ' + k + ': done ' + b.done + ', open ' + b.open + ', cancelled ' + b.cancelled + ', moved at least once ' + b.moved);
}

if (weekDetail) out.push('', 'CALENDAR, this week and next (only for sizing next week\'s goals; never review or ask about these events; this week: ' + calHours + ' h of timed events)');
for (const e of events) out.push('- ' + DateTime.fromISO(e.day).setLocale('en').toFormat('ccc yyyy-LL-dd') + ' · ' + e.title + (e.hours !== null ? ' · ' + e.hours + ' h' : ' · all day'));

out.push('', 'IDEAS (not Dropped)');
if (!ideas.filter(i => i.status !== 'Dropped').length) out.push('None.');
for (const i of ideas.filter(i => i.status !== 'Dropped')) {
  out.push('- ' + i.name + ' [id ' + i.id + '] · ' + show(i.status) + ' · verdict ' + show(i.verdict) + ' · success: ' + show(i.metric) + ' target ' + show(i.target) + ' · test: ' + show(i.test) + ' by ' + show(i.testBy));
}

// The goals card for Telegram: the Plan week's goals (on Saturday and Sunday the coming week) with their tasks done.
// Package Projects Reply shows it only when the Coach's reply asks for it with the line "[card: goals]".
const cardWeek = $now.weekday >= 6 ? $now.plus({ weeks: 1 }) : $now;
const cardMon = cardWeek.startOf('week').toISODate();
const cardSun = cardWeek.endOf('week').toISODate();
const progressGoals = plan.filter(i => i.type === 'Goal' && i.status !== 'Cancelled' && i.due >= cardMon && i.due <= cardSun).map(i => {
  const ts = (tree.tasks || []).filter(t => t.weekly_item === i.id && t.status !== 'Cancelled');
  return { name: i.name, done: ts.filter(t => t.status === 'Done').length, total: ts.length, tasks: [] };
});
const progress = progressGoals.length ? { title: 'Weekly goals · week ending ' + cardWeek.endOf('week').setLocale('en').toFormat('ccc d LLL'), goals: progressGoals } : {};
// A report (the weekly review, scheduled or asked) is built from Notion only: the agent gets no chat history for it
const report = /AUTOMATIC WEEKLY REVIEW|\bweekly review\b|how did my week go/i.test(String(trig.chatInput || ''));
// A MEMORY UPDATE note from "Read Plan Tree" (a rename or status change found by Notion page id) goes first, so the Coach sees it this turn; Prepare Memory Writes keeps it in the chat memory for later turns
const memNote = (() => { try { return String($('Read Plan Tree').first().json.memory_note || ''); } catch (e) { return ''; } })();
return [{ json: { chat_id: trig.chat_id, agent_name: trig.agent_name, chatInput: trig.chatInput, snapshot: (memNote ? memNote + '\n\n' : '') + out.join('\n'), progress, report } }];

// Notion writes this turn REALLY made, read from the agent's own tool calls and Notion's answers (never from the reply text).
// A write whose answer carries no saved id is left out: nothing was saved.
// Each line names the row (title from this run's reads or from the write itself) and the fields written, so memory alone shows what changed.
const SOURCES = ["Fetch Open Projects", "Fetch Recent Reviews", "Fetch Week Plan", "Fetch Week Tasks", "Fetch Project Ideas"];
const out = $input.first().json;
const trig = $('Execute Workflow Trigger').first().json;
const WRITE = /create|update|add|confirm|mark|delete|trash|archive|log weekly/i;
const ID = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g;
const TITLE_KEYS = ['Task Name', 'Subtask Name', 'Description', 'Name', 'Review', 'Title'];
const names = {};
const titleOf = (o) => {
  if (typeof o.name === 'string' && o.name) return o.name;
  if (typeof o.summary === 'string' && o.summary) return o.summary;
  for (const [k, v] of Object.entries(o.properties || {})) {
    if (v && v.type === 'title') return (v.title || []).map(t => t.plain_text).join('');
    if (TITLE_KEYS.includes(k) && typeof v === 'string') return v;
  }
  return null;
};
const collect = (x, depth = 0) => {
  if (depth > 8) return;
  if (typeof x === 'string') { if (!/^\s*[\[{]/.test(x)) return; try { x = JSON.parse(x); } catch (e) { return; } }
  if (Array.isArray(x)) { x.forEach(v => collect(v, depth + 1)); return; }
  if (!x || typeof x !== 'object') return;
  if (typeof x.id === 'string' && !names[x.id]) { const t = titleOf(x); if (t) names[x.id] = t; }
  for (const v of Object.values(x)) if (v && (typeof v === 'object' || typeof v === 'string')) collect(v, depth + 1);
};
for (const n of SOURCES) { try { collect($(n).all().map(i => i.json)); } catch (e) { /* that read did not run */ } }
const steps = out.intermediateSteps || [];
for (const s of steps) collect(s.observation);
const short = (v) => (typeof v === 'string' ? v : JSON.stringify(v)).replace(/\s+/g, ' ').slice(0, 150);
const lines = [];
for (const step of steps) {
  const tool = String((step.action && step.action.tool) || '');
  if (!WRITE.test(tool)) continue;
  const obs = typeof step.observation === 'string' ? step.observation : JSON.stringify(step.observation ?? '');
  // An error answer saved nothing, even though it carries ids (request_id, integration_id, the data_source id)
  if (/APIResponseError|"error"\s*:|object_not_found|validation_error|Could not find|MCP error|timed out/i.test(obs)) continue;
  const ids = [...new Set(obs.match(ID) || [])];
  if (!ids.length || /"properties":\{\}/.test(obs)) continue;
  const inp = (step.action && step.action.toolInput) ?? {};
  const label = (id) => (names[id] ? '"' + names[id] + '" (' + id + ')' : id);
  // ids already in the input are the row being updated or rows the new one links to; the others are the rows just created
  const inInput = JSON.stringify(inp);
  const isCreate = /create|add/i.test(tool);
  const saved = isCreate ? ids.filter(id => !inInput.includes(id)) : ids;
  const linked = isCreate ? ids.filter(id => inInput.includes(id)) : [];
  const fields = (p) => Object.entries(p).map(([k, v]) => k + ' = ' + short(v)).join('; ');
  const props = inp && typeof inp === 'object' && inp.properties && typeof inp.properties === 'object' && !Array.isArray(inp.properties) ? inp.properties : null;
  const pages = inp && typeof inp === 'object' && Array.isArray(inp.pages) ? inp.pages : null;
  const written = props ? fields(props) : pages ? pages.map(p => fields(p.properties || {})).join(' || ') : JSON.stringify(inp).replace(/\s+/g, ' ').slice(0, 700);
  lines.push('- ' + tool + ' -> saved in Notion: ' + (saved.length ? saved : ids).map(label).join(', ') + (linked.length ? ' | linked to: ' + linked.map(label).join(', ') : '') + ' | written: ' + written);
}
const action_log = lines.length
  ? '[ACTION LOG, ' + $now.toFormat('yyyy-LL-dd HH:mm') + ', written by the workflow from the tool results of my previous reply: these Notion writes are DONE. Never make them again.]\n' + lines.join('\n')
  : '';
const { intermediateSteps, ...reply } = out;
// The agent sometimes copies an earlier action log from its chat memory into its reply: never send it
if (typeof reply.output === 'string') reply.output = reply.output.replace(/\s*\[ACTION LOG[^\]\n]*\][^\n]*(\n- [^\n]*)*/g, '').trim();
return [{ json: { ...reply, chat_id: String(trig.chat_id ?? ''), agent_name: trig.agent_name || 'project', action_log } }];

// What this turn adds to the Coach's chat memory (Postgres), saved in one go by Save To Memory, in this order:
// 0. a weekly review (scheduled or asked, also days later) ran with NO chat history: the chat is emptied first ('clear'),
//    so every review starts a clean conversation from fresh Notion data and later replies continue from it;
// 1. the MEMORY UPDATE note from "Read Plan Tree" (a project or goal renamed, or a project's status changed, matched by Notion page id);
//    the Coach already saw it in its snapshot this turn, the memory keeps it for later turns;
// 2. for a review: its question and answer;
// 3. the ACTION LOG: the Notion writes this turn really made (from Build Action Log).
// Messages are stored exactly as the Chat Memory Manager stored them (notes and logs hidden).
const snap = $('Build Projects Snapshot').first().json;
const session_id = 'demo-' + snap.chat_id + '-' + snap.agent_name;
const note = String($('Read Plan Tree').first().json.memory_note || '');
const log = String($('Build Action Log').first().json.action_log || '');
const human = (content) => ({ type: 'human', content, additional_kwargs: {}, response_metadata: {} });
const ai = (content, hidden) => ({ type: 'ai', content, tool_calls: [], additional_kwargs: hidden ? { hideFromUI: true } : {}, response_metadata: {}, invalid_tool_calls: [] });
const writes = [];
const add = (message) => writes.push({ op: 'add', session_id, message });
if (snap.report === true) writes.push({ op: 'clear', session_id });
if (note) add(ai(note, true));
if (snap.report === true) {
  add(human(String(snap.chatInput || '')));
  add(ai(String($('Projects Coach').first().json.output || '')));
}
if (log) add(ai(log, true));
return [{ json: { writes } }];
